"""Assemble independent scene exports, never an earlier master; keep exact source EDL."""
from pathlib import Path
import subprocess,json
r=Path(__file__).resolve().parents[1];s1=r.parent/'scene-01-v5';manifest={'status':'Draft – Pending Review','fps':30,'resolution':[1920,1080],'duration':184,'scenes':[],'assembly':'Stream-copy concat of independent final scene sources; no previous master, no repeated master recompression.'}
for lang in ['AR','EN']:
 for variant in ['Clean','Preview']:
  a=s1/f'outputs/Scene-01_Business-Expansion_{lang}_V5_{variant}.mp4';b=r/f'scene02/outputs/Scene-02_Broken-RTL_{lang}_V5_{variant}.mp4';lst=r/f'master/concat-{lang}-{variant}.txt';lst.write_text(f"file '{a}'\nduration 50\nfile '{b}'\nduration 134\n")
  o=r/f'master/outputs/CoffeeBreakWeb_RTL-Migration_{lang}_Master_V1_{variant}.mp4'
  if o.exists():raise RuntimeError(f'Refusing to overwrite {o}')
  subprocess.run(['ffmpeg','-v','error','-f','concat','-safe','0','-i',str(lst),'-map','0:v','-map','0:a','-c','copy','-movflags','+faststart',str(o)],check=True)
  manifest['scenes'].append({'language':lang,'variant':variant,'sources':[str(a),str(b)],'timeline':[[0,50],[50,184]],'source_in_out':[[0,50],[0,134]],'transition':'Natural cut from Scene01 question to genuine Study terminal; existing end effects decay before cut. No repeated 10-second geography, product or requirement segment. Scene02 has its own shorter language context, preserving the standalone scene.','audio':['scene-01-v5/audio/SFX-Mix.wav','scene02/audio/SFX-Mix.wav'],'captions':['scene-01-v5/timeline/voiceover.json','scene02/voiceover.json'],'clean_definition':'Defect labels and SFX retained; narration guide captions removed.'})
(r/'master/timeline.json').write_text(json.dumps(manifest,indent=2))
lines=['# Master Video Scene Manifest','\n**Draft – Pending Review** ·184s ·1920×1080 ·30FPS ·H.264/AAC.','\n|Order|Timeline|Source|Source in/out|Transition|Audio|Captions|','|---|---|---|---|---|---|---|','|1|0–50s|Scene-01_Business-Expansion_{AR,EN}_V5_{Clean,Preview}.mp4|0–50s|Original approved Scene01 ending/question|Original Scene01 SFX|Scene01 guide track only in Preview|','|2|50–184s|Scene-02_Broken-RTL_{AR,EN}_V5_{Clean,Preview}.mp4|0–134s|Natural editorial cut into actual terminal, then real app|Separate Scene02 procedural SFX|Scene02 editable guide track only in Preview|','\nIndividual Scene01 source remains assets/scene-01-v5; individual Scene02 source remains this production folder/source and scene02/timeline.json. Exact absolute input/output paths are in timeline.json. No previous master video is an input. Independent scene streams are copied into master, avoiding another full re-encode.','\nScene01 teaser repeats three brief previews by design; Scene02 supplies their detailed evidence and explanations. Two language switches remain intentionally contextual: Invoicing and Procurement each use their actual selector. The short standalone English setup follows Scene01’s teaser; no duplicate business narration was added. It is not accurate to claim zero repeated UI content.','\nOriginal Scene01 presenter silhouette remains replaceable. No new presenter or narration was generated. Original Scene0150s preserved in full; changing that approved duration would be a separate review. Future narration may require retiming individual scenes, then regenerate this EDL.','\nSeparate AR/EN and Clean/Preview timelines; all have the same scene order/in/out. Scene01 SFX peak≈−18.8dBFS and Scene02≈−18.8dBFS; effects fade locally and reserve voice headroom. No continuous music, no abrupt cut through a live voice.']
(r/'master/Master-Video-Scene-Manifest.md').write_text('\n'.join(lines));print('Master assembled from independent scenes.')
